mapper.sql:
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.Mear_Id = #{params.mearId}


    and INSTR(mn.Mearc_Uname,#{params.mearcUname})


    and INSTR(mn.Mearc_Node_Name,#{params.mearcNodeName})

mapper.select:
select c1.C_Name as mearcCName, c1.C_Abbreviation as mearcCAbbName, (select count(*) from SYS_FileAnnex where File_Relation_Id=mn.Mearc_File and upload_status=1 and ARCHIVE=0 and File_Replace=0) as mearcFileCount, mn.* from Con_Measure_Record_Check mn left join SYS_Company c1 on c1.C_Id = mn.Mearc_Cid
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Mearc_Time desc
